-- SOLO SELECT/SHOW. Seleccionar y verificar manualmente la base destino. Ejecutar por separado.
-- Metadata puede no ser visible sin permisos; ausencia no es certificacion.
SELECT DATABASE() base,VERSION() version,@@foreign_key_checks fk,@@check_constraint_checks ck,@@sql_mode sql_mode;
SHOW GRANTS;
-- DETENER si la base/version no corresponde o FK/CHECK no son 1.
-- CERO filas esperado: cualquier tabla nueva visible exige detener por instalacion previa/parcial.
SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('flota_cb2_fondos_vinculos');
WITH requeridas AS (SELECT 'usuarios' tabla,'id' columna UNION ALL SELECT 'flota_cb2_consumos','empresa_id' UNION ALL SELECT 'flota_cb2_consumos','proveedor_id' UNION ALL SELECT 'flota_cb2_consumos','id' UNION ALL SELECT 'tms_solicitud_fondo_lineas','empresa_id' UNION ALL SELECT 'tms_solicitud_fondo_lineas','id') SELECT r.*,c.COLUMN_TYPE,c.IS_NULLABLE,t.ENGINE FROM requeridas r LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=r.tabla AND c.COLUMN_NAME=r.columna LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE c.COLUMN_NAME IS NULL OR c.DATA_TYPE<>'int' OR c.COLUMN_TYPE LIKE '%unsigned%' OR c.IS_NULLABLE<>'NO' OR COALESCE(t.ENGINE,'')<>'InnoDB';
WITH requeridos AS (SELECT 'flota_cb2_consumos' tabla,'uq_cb2c_ambito' indice,'empresa_id,proveedor_id,id' columnas,0 no_unico UNION ALL SELECT 'usuarios','PRIMARY','id',0 UNION ALL SELECT 'tms_solicitud_fondo_lineas','uq_fondolin_c2a_empresa_id','empresa_id,id',0) SELECT r.*,'INDICE_INCOMPATIBLE_O_FALTANTE' problema FROM requeridos r WHERE NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=r.tabla AND s.INDEX_NAME=r.indice GROUP BY s.INDEX_NAME HAVING MAX(s.NON_UNIQUE)=r.no_unico AND MIN(s.NON_UNIQUE)=r.no_unico AND GROUP_CONCAT(s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX)=r.columnas AND SUM(s.SUB_PART IS NOT NULL)=0 AND MIN(s.INDEX_TYPE)='BTREE');
-- CERO esperado: nombres FK ya ocupados en el esquema.
SELECT TABLE_NAME,CONSTRAINT_NAME FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN('fk_cb2fv_consumo','fk_cb2fv_linea','fk_cb2fv_actor');
